const nano_focus_t *nano_focus(uint32_t type)
{
    for (size_t i = 0; i < sizeof(FOCUS) / sizeof(FOCUS[0]); i++) {
        if (FOCUS[i].type == type) return &FOCUS[i];
    }
    return NULL;
}
